} class VipDiscount implements DiscountStrategy { @override double call(double originalPrice) => originalPrice * 0.20; // 2
} class RegularDiscount implements DiscountStrategy { @override double call(double originalPrice) => originalPrice * 0.10; // 2a
} class NoDiscount implements DiscountStrategy { @override double call(double originalPrice) => 0.0; // 2b
} class ShoppingCart { DiscountStrategy _discountStrategy; // 3 ShoppingCart(this._discountStrategy); set discountStrategy(DiscountStrategy strategy) => // 3a _discountStrategy = strategy; double calculatePrice(double originalPrice) => // 4 originalPrice - _discountStrategy(originalPrice);
} void main() { const price = 100.0; final cart = ShoppingCart(RegularDiscount()); print('Price with regular discount: \$${cart.calculatePrice(price)}'); // Output: Price with regular discount: $90.0 cart.discountStrategy = VipDiscount(); print('Price with vip discount: \$${cart.calculatePrice(price)}'); // Output: Price with vip discount: $80.0 cart.discountStrategy = NoDiscount(); print('Price with no discount: \$${cart.calculatePrice(price)}'); // Output: Price with no discount: $100.0
} DiscountStrategy 是折扣策略的接口（interface）; VipDiscount、RegularDiscount和NoDiscount是3个具体的折扣策略，它们都实现（implements）了DiscountStrategy ; ShoppingCart代表购物车，它聚合了一个 DiscountStrategy ; calculatePrice方法负责计算最终的价格（原价 - 折扣）;

