下例中Point2类 重写了 Object.hashCode 与 Object.== ，而 Point类使用了其默认实现。 // ex661.dart
void main() { var a = Point(1, 2); var b = Point(1, 2); var c = Point2(1, 2); var d = Point2(1, 2); print('a.hashCode: ${a.hashCode}'); // 1 print('b.hashCode: ${b.hashCode}'); // 1a print('c.hashCode: ${c.hashCode}'); // 2 print('d.hashCode: ${d.hashCode}'); // 2a assert(a != b); // 3 assert(c == d); // 3a var set1 = {a, b, c, d}; // 4 print(set1); // Output: {Point(1, 2), Point(1, 2), Point2(1, 2)} var map1 = {a: 'a', b: 'b', c: 'c', d: 'd'}; // 5 print(map1); // Output: {Point(1, 2): a, Point(1, 2): b, Point2(1, 2): d}
} class Point { final int x, y; Point(this.x, this.y); @override String toString() => 'Point($x, $y)';
} class Point2 { final int x, y; Point2(this.x, this.y); @override String toString() => 'Point2($x, $y)'; @override int get hashCode { const prime = 31; var result = 1; result = prime * result + x.hashCode; result = prime * result + y.hashCode; return result; } @override bool operator ==(Object other) { if (other is Point2) { return x == other.x && y == other.y; } return false; }
} 变量a,b的类型为Point，虽然它们的成员变量（x和y）的值都一样，但它们的哈希值不同（原因是它们的对象标识不同）； 变量c,d的类型为Point2，它们的哈希值相同（因为我们重写了Object.hashCode 与 Object.==，只要它们的成员变量具有相同的值，它们的哈希值就一定相同）； a != b 且 c == d，显然成立； 由于 c==d 成立， set1 只有3个元素； 同理 map1只有3个entries，map1内部将c和d视为同样的key（即Point2(1, 2)），与其对应的value是最新的那个值'd'。

