import 'dart:io'; void main() { final dir = Directory('.'); traversal(dir).listen((f) => print(f.path));
} Stream<File> traversal(Directory dir) async* { final entities = await dir.list().toList(); // 1 for (var entity in entities) { if (entity is File) { yield entity; // 2 } else if (entity is Directory) { yield* traversal(entity); // 3 } }
