import 'dart:typed_data'; void main() async { final mainReceivePort = ReceivePort(); await Isolate.spawn(worker, mainReceivePort.sendPort); // 1 // 准备数据并包装 final Uint8List massiveData = Uint8List(100 * 1024 * 1024); // 100MB final transferable = TransferableTypedData.fromList([massiveData]); // 3 mainReceivePort.listen((message) { if (message is SendPort) { var workerSendPort = message; print('Main 发送 100MB 数据...'); workerSendPort.send(transferable); // 4 // 发送后 massiveData 在 Main Isolate 中将不再可用 } else { print(message); // 8 mainReceivePort.close(); // 8a } });
} void worker(SendPort mainSendPort) { final receivePort = ReceivePort(); mainSendPort.send(receivePort.sendPort); // 2 receivePort.listen((message) { final transferable = message as TransferableTypedData; // 获取原始字节流（零拷贝） final Uint8List bytes = transferable .materialize() // 5 materialize .asUint8List(); // 6 asUint8List mainSendPort.send('Worker 收到 ${bytes.length / 1024 ~/ 1024} MB'); // 7 });
} sequenceDiagram autonumber participant M as Main Isolate participant W as Worker Isolate participant RAM as Shared Memory (C Heap) M-&gt;&gt;+W: Isolate.spawn(worker, mainSendPort) Note over W: 初始化 ReceivePort W-&gt;&gt;M: mainSendPort.send(workerSendPort) Note over M: 准备 100MB Uint8List M-&gt;&gt;RAM: TransferableTypedData.fromList([massiveData]) Note right of RAM: 数据从 Dart Heap 移动到可跨界访问的 C Heap M-&gt;&gt;W: workerSendPort.send(transferable) Note over M: massiveData 在此变为不可用 (Empty) rect rgb(240, 248, 255) Note over W: 收到消息 (transferable) W-&gt;&gt;RAM: transferable.materialize() Note right of RAM: 字节流映射到 Worker 的内存地址 W-&gt;&gt;W: 得到 Uint8List bytes end W-&gt;&gt;M: mainSendPort.send("Worker 收到 100 MB") M--&gt;&gt;M: 打印消息并关闭 ReceivePort a. 握手 (Steps 2-3)： 由于 Isolate.spawn() 只能让主 Isolate 拿到 Worker 的句柄，反向通信需要 Worker 先通过 mainSendPort 把自己的 workerSendPort 发送回去。这是建立双向通信的标准做法。 b. 内存转移 (Step 4 & 6)： TransferableTypedData.fromList 是核心。它将数据从 Dart 的普通堆（Heap）中移出，放到一个可以被多个 Isolate 访问的底层缓冲区（通常是 C 堆）。 Main 丢失：一旦 send(transferable) 执行，主 Isolate 就不再拥有这块数据。 Worker 获得：Worker 调用 materialize() 后，这块内存被“绑定”到 Worker 空间。 c. 零拷贝的本质： 数据本身在物理内存（RAM）中并没有被复制，只是访问权限从 Main 转移到了 Worker。

